=head2 Google::Cloud::Metastore::V1alpha::Metastore::HiveMetastoreConfig

Specifies configuration information specific to running Hive metastore
software as the metastore service.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->version() >> / C<< $msg->version($value) >>

Type: C<String>

Immutable. The Hive metastore schema version.

=item * C<< $msg->config_overrides() >> / C<< $msg->config_overrides($value) >>

Type: C<Message> (L<Google::Cloud::Metastore::V1alpha::Metastore::HiveMetastoreConfig::ConfigOverridesEntry>)

A mapping of Hive metastore configuration key-value pairs to apply to the
Hive metastore (configured in `hive-site.xml`). The mappings
override system defaults (some keys cannot be overridden). These
overrides are also applied to auxiliary versions and can be further
customized in the auxiliary version's `AuxiliaryVersionConfig`.

=item * C<< $msg->kerberos_config() >> / C<< $msg->kerberos_config($value) >>

Type: C<Message> (L<Google::Cloud::Metastore::V1alpha::Metastore::KerberosConfig>)

Information used to configure the Hive metastore service as a service
principal in a Kerberos realm. To disable Kerberos, use the `UpdateService`
method and specify this field's path
(`hive_metastore_config.kerberos_config`) in the request's `update_mask`
while omitting this field from the request's `service`.

=item * C<< $msg->endpoint_protocol() >> / C<< $msg->endpoint_protocol($value) >>

Type: C<Enum> (L<Google::Cloud::Metastore::V1alpha::HiveMetastoreConfig::EndpointProtocol>)

The protocol to use for the metastore service endpoint. If unspecified,
defaults to `THRIFT`.

=item * C<< $msg->auxiliary_versions() >> / C<< $msg->auxiliary_versions($value) >>

Type: C<Message> (L<Google::Cloud::Metastore::V1alpha::Metastore::HiveMetastoreConfig::AuxiliaryVersionsEntry>)

A mapping of Hive metastore version to the auxiliary version
configuration. When specified, a secondary Hive metastore service is
created along with the primary service. All auxiliary versions must be less
than the service's primary version. The key is the auxiliary service name
and it must match the regular expression [a-z]([-a-z0-9]*[a-z0-9])?. This
means that the first character must be a lowercase letter, and all the
following characters must be hyphens, lowercase letters, or digits, except
the last character, which cannot be a hyphen.

=back

=head3 Enum: HiveMetastoreConfig::EndpointProtocol

=over 4

=item * C<ENDPOINT_PROTOCOL_UNSPECIFIED> => C<0>

=item * C<THRIFT> => C<1>

=item * C<GRPC> => C<2>

=back

